1	{
2	  "$schema": "https://json-schema.org/draft/2020-12/schema",
3	  "$id": "arch-audit@1",
4	  "title": "Architecture Audit",
5	  "description": "Result of checking a draft spec@1 against the workspace's persisted arch-model@1 for architectural fit — boundary violations, competing abstractions, and invariant conflicts. Produced by scribe:arch-auditor in check mode. Not a binding verdict; a fail routes back to scribe/draft-spec the same way an audit-spec fail does, under the same 2-round circuit breaker.",
6	  "type": "object",
7	  "required": ["issues", "overall"],
8	  "additionalProperties": false,
9	  "properties": {
10	    "issues": {
11	      "type": "array",
12	      "items": {
13	        "type": "object",
14	        "required": ["type", "description", "suggested_fix"],
15	        "additionalProperties": false,
16	        "properties": {
17	          "type": {
18	            "enum": ["boundary-violation", "competing-abstraction", "invariant-conflict", "missing-model-coverage"],
19	            "description": "boundary-violation: spec implies a dependency running against a module's allowed direction. competing-abstraction: spec introduces a new type/interface for a concept the model already canonicalizes. invariant-conflict: spec conflicts with a modeled invariant. missing-model-coverage: spec touches an area the model doesn't describe — not itself a defect, but a gap worth noting."
20	          },
21	          "description": { "type": "string" },
22	          "location": { "type": "string", "description": "File path or module name the issue concerns, if applicable" },
23	          "suggested_fix": { "type": "string", "description": "The rewritten fix, not just a description of the problem" }
24	        }
25	      }
26	    },
27	    "overall": {
28	      "enum": ["pass", "fail"],
29	      "description": "pass only if no boundary-violation, competing-abstraction, or invariant-conflict issues exist. missing-model-coverage alone never fails the audit."
30	    },
31	    "model_updates_suggested": {
32	      "type": "array",
33	      "items": { "type": "string" },
34	      "description": "Things noticed during the check that the model itself should learn (a new module, a new canonical abstraction) without triggering a full rebuild."
35	    },
36	    "reasoning": {
37	      "type": "string",
38	      "description": "Agent scratchpad — not consumed downstream"
39	    }
40	  }
41	}
42

