14	        "required": ["name", "path", "responsibility"],
15	        "additionalProperties": false,
16	        "properties": {
17	          "name": { "type": "string" },
18	          "path": { "type": "string", "description": "Workspace-relative path to the module, package, or crate root" },
19	          "responsibility": { "type": "string", "description": "One paragraph: what this module owns and why it exists as a separate boundary" },
20	          "depends_on": {
21	            "type": "array",
22	            "items": { "type": "string" },
23	            "description": "Names of other modules this one is allowed to depend on. A dependency running the other direction is a boundary violation."
24	          }
25	        }
26	      },
27	      "description": "The boundary map — every module the model tracks, its responsibility, and its allowed dependency direction."
28	    },
29	    "canonical_abstractions": {
30	      "type": "array",
31	      "items": {
32	        "type": "object",
33	        "required": ["concept", "type_or_interface", "location"],
34	        "additionalProperties": false,
35	        "properties": {
36	          "concept": { "type": "string", "description": "The domain concept this abstraction represents (e.g. 'user identity', 'retry policy')" },
37	          "type_or_interface": { "type": "string", "description": "The canonical type, trait, or interface name" },
38	          "location": { "type": "string", "description": "File path where the canonical definition lives" },
39	          "rationale": { "type": "string", "description": "Why this is the one representation new code should reuse rather than reinvent" }
40	        }
41	      },
42	      "description": "The registry of 'this is the one true representation of X' — a new spec introducing a competing type for an already-modeled concept is a finding, not a fresh design choice."
43	    },
44	    "invariants": {
45	      "type": "array",
46	      "items": {
47	        "type": "object",
48	        "required": ["name", "rule", "rationale"],
49	        "additionalProperties": false,
50	        "properties": {
51	          "name": { "type": "string" },
52	          "rule": { "type": "string", "description": "The rigid architectural property that must hold" },
53	          "rationale": { "type": "string" },
54	          "enforced_by": { "type": "string", "description": "The test, type check, or lint that fails if this invariant is violated, if one exists" }
55	        }
56	      },
57	      "description": "System-wide invariants — cumulative across every structural fix scribe:architect has ever produced, plus any the build pass surfaced directly."
58	    },
59	    "last_built_from": {
60	      "type": "string",
61	      "description": "Commit hash or other repository state marker the model was last built or refreshed against. Absence means staleness cannot be assessed — treat as a coverage gap, not proof the model is current."
62	    },
63	    "reasoning": {
64	      "type": "string",
65	      "description": "Agent scratchpad — not consumed downstream"
66	    }
67	  }
