3	  "$id": "arch-spec@1",
4	  "title": "Architectural Spec",
5	  "description": "A structural specification for internal refactoring, trait extraction, AST transforms, and subsystem invariants where types and architectural invariants are the primary contract.",
6	  "type": "object",
7	  "required": ["id", "purpose", "scope", "target_crates", "architectural_invariants", "trait_contracts", "acceptance_criteria"],
8	  "additionalProperties": false,
9	  "properties": {
10	    "id": {
11	      "type": "string",
12	      "description": "Unique identifier (e.g. ARCH-SPEC-001)"
13	    },
14	    "purpose": {
15	      "type": "string",
16	      "description": "Why this structural refactoring is required and the defect class or bottleneck it eliminates."
17	    },
18	    "scope": {
19	      "type": "string",
20	      "description": "Crates, modules, and data structures touched by this refactor."
21	    },
22	    "target_crates": {
23	      "type": "array",
24	      "minItems": 1,
25	      "items": { "type": "string" },
26	      "description": "List of crate names or workspace packages involved in this architectural refactor."
27	    },
28	    "non_goals": {
