15	        "additionalProperties": false,
16	        "properties": {
17	          "type": {
18	            "enum": ["boundary-violation", "competing-abstraction", "invariant-conflict", "missing-model-coverage"],
19	            "description": "boundary-violation: spec implies a dependency running against a module's allowed direction. competing-abstraction: spec introduces a new type/interface for a concept the model already canonicalizes. invariant-conflict: spec conflicts with a modeled invariant. missing-model-coverage: spec touches an area the model doesn't describe — not itself a defect, but a gap worth noting."
20	          },
